# DAG 工作流引擎
class WorkflowEngine:
    def __init__(self):
        self.tasks = {}
        self.dependencies = {}

    def add_task(self, task_id, func, deps=None):
        self.tasks[task_id] = func
        self.dependencies[task_id] = deps or []

    def execute(self):
        order = self._topological_sort()
        results = {}
        for task_id in order:
            deps_met = all(d in results for d in self.dependencies[task_id])
            if deps_met:
                results[task_id] = self.tasks[task_id](results)
        return results
